from django.db import models
from ..models import TimeStampedModel,WorkflowInstance,WorkflowState
class CostRate(TimeStampedModel):name=models.CharField(max_length=160);key=models.SlugField(unique=True);unit=models.CharField(max_length=30);rate=models.DecimalField(max_digits=12,decimal_places=4);currency=models.CharField(max_length=3,default='USD')
class CostEvent(models.Model):instance=models.ForeignKey(WorkflowInstance,related_name='cost_events',on_delete=models.CASCADE);state=models.ForeignKey(WorkflowState,null=True,on_delete=models.SET_NULL);rate=models.ForeignKey(CostRate,on_delete=models.PROTECT);quantity=models.DecimalField(max_digits=14,decimal_places=4);amount=models.DecimalField(max_digits=14,decimal_places=4);metadata=models.JSONField(default=dict);occurred_at=models.DateTimeField(auto_now_add=True)
class InstanceCostSummary(TimeStampedModel):instance=models.OneToOneField(WorkflowInstance,related_name='cost_summary',on_delete=models.CASCADE);labor=models.DecimalField(max_digits=14,decimal_places=2,default=0);system=models.DecimalField(max_digits=14,decimal_places=2,default=0);external=models.DecimalField(max_digits=14,decimal_places=2,default=0);total=models.DecimalField(max_digits=14,decimal_places=2,default=0);currency=models.CharField(max_length=3,default='USD')
